eaded. public Vector3 CurrentWaypoint { get; private set; } public bool HasWaypoint { get; private set; } private void Start() { // an array of the positions of all the waypoints in the path Vector3[] waypoints = new Vector3[pathHolder.childCount]; for (int i = 0; i < waypoints.Length; i++) { waypoints[i] = pathHolder.GetChild(i).position; waypoints[i] = new Vector3(waypoints[i].x, transform.position.y, waypoints[i].z); } StartCoroutine(FollowPath(waypoints)); } IEnumerator FollowPath(Vector3[] waypoints) { transform.position = waypoints[0]; int targetWaypointIndex = 1; // since we're already at point 0 Vector3 targetWaypoint = waypoints[targetWaypointIndex]; CurrentWaypoint = targetWaypoint; HasWaypoint = true; while (true) { transform.position = Vector3.MoveTowards(transform.position, targetWaypoint, speed * Time.deltaTime); if (transform.position == targetWaypoint) { targetWaypointIndex = (targetWaypointIndex + 1) % waypoints.Length; // when index reaches waypoints.Length it wraps back to 0 targetWaypoint = waypoints[targetWaypointIndex]; CurrentWaypoint = targetWaypoint; yield return new WaitForSeconds(waitTime); } yield return null; } } void OnDrawGizmos() { if (pathHolder == null) return; // avoids a null-ref before you assign it Vector3 startPosition = pathHolder.GetChild(0).position; Vector3 previousPosition = startPosition; foreach (Transform waypoint in pathHolder) { Gizmos.DrawSphere(waypoint.position, 0.2f); Gizmos.DrawLine(previousPosition, waypoint.position); previousPosition = waypoint.position; } Gizmos.DrawLine(previousPosition, startPosition); } }